module @_QMcoarray {

  // Coarray token — compile-time registration handle
  fir.global @_QFcoarray_halo_exchangeEa.token
      : !fir.ref<none>   // opaque token, managed by OpenCoarrays runtime

  func.func @_QPcoarray_halo_exchange(
      %arg0: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "a", fir.inout},
      %arg1: !fir.ref<i32>               {fir.bindc_name = "n", fir.in}
  ) {
    %c1     = arith.constant 1 : index
    %c1_i32 = arith.constant 1 : i32
    %c4     = arith.constant 4 : index   // sizeof(f32)

    // THIS_IMAGE() and NUM_IMAGES() → runtime calls
    %me   = fir.call @_caf_this_image() : () -> i32
    %nimg = fir.call @_caf_num_images() : () -> i32

    // Load n and compute shape
    %n_val = fir.load %arg1 : !fir.ref<i32>
    %n_idx = fir.convert %n_val : (i32) -> index
    %shape = fir.shape %n_idx : (index) -> !fir.shape<1>

    // if (me > 1)
    %me_gt1 = arith.cmpi sgt, %me, %c1_i32 : i32
    fir.if %me_gt1 {

      // a(n)[me-1]: remote read via _caf_get
      // src image = me - 1
      %src_img = arith.subi %me, %c1_i32 : i32

      // Compute byte offset of a(n): (n-1) * sizeof(f32)
      %n_m1   = arith.subi %n_idx, %c1 : index
      %offset = arith.muli %n_m1, %c4  : index
      %offset_i64 = fir.convert %offset : (index) -> i64

      // Token for this coarray
      %token = fir.address_of(@_QFcoarray_halo_exchangeEa.token) : !fir.ref<none>

      // Destination: a(1) — local element 0, byte offset 0
      %dst_ptr = fir.coordinate_of %arg0, %c1 : (!fir.ref<!fir.array<?xf32>>, index) -> !fir.ref<f32>

      // _caf_get(token, image, src_byte_offset, dst_ptr, element_size, n_elements)
      fir.call @_caf_get(%token, %src_img, %offset_i64, %dst_ptr, %c4, %c1)
                 : (!fir.ref<none>, i32, i64, !fir.ref<f32>, index, index) -> ()
    }

    // SYNC ALL → barrier
    fir.call @_caf_sync_all() : () -> ()
    return
  }
}
