      %arg1: !fir.ref<i32>               {fir.bindc_name = "n", fir.in}
  ) {
    %n_val  = fir.load %arg1 : !fir.ref<i32>
    %n_idx  = fir.convert %n_val : (i32) -> index
    %shape  = fir.shape %n_idx : (index) -> !fir.shape<1>

    // hlfir.declare for the coarray argument
    // Note: coarray attribute is carried in fortran_attrs
    %a:2 = hlfir.declare %arg0(%shape)
        {fortran_attrs = #fir.var_attrs<intent_inout, target>,
         uniq_name = "_QFcoarray_halo_exchangeEa"}
        : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>)
       -> (!fir.box<!fir.array<?xf32>>, !fir.ref<!fir.array<?xf32>>)

    // Intrinsics: THIS_IMAGE and NUM_IMAGES lower to direct runtime calls
    %me   = fir.call @_caf_this_image() : () -> i32
    %nimg = fir.call @_caf_num_images() : () -> i32

    %c1   = arith.constant 1 : i32
    %cond = arith.cmpi sgt, %me, %c1 : i32

    fir.if %cond {
      // a(n)[me-1]: coarray remote access → _caf_get
      %src_img = arith.subi %me, %c1 : i32
      // byte offset for element n: (n_idx-1)*4
      %n_m1   = arith.subi %n_idx, 1 : index
      %offset = arith.muli %n_m1, 4 : index
      %off64  = fir.convert %offset : (index) -> i64
      %token  = fir.address_of(@_QFcoarray_halo_exchangeEa.token) : !fir.ref<none>
      %dst_ref = fir.coordinate_of %a#1, 1 : (!fir.ref<!fir.array<?xf32>>, index) -> !fir.ref<f32>
      fir.call @_caf_get(%token, %src_img, %off64, %dst_ref, 4, 1)
                 : (!fir.ref<none>, i32, i64, !fir.ref<f32>, index, index) -> ()
    }
    fir.call @_caf_sync_all() : () -> ()
    return
  }
}
